// Real, freely-licensed videos harvested from the Wikimedia Commons API.
// Titles, authors, licences, durations and file URLs are the genuine values
// Commons returned via prop=imageinfo|videoinfo - nothing here is invented.
//
// Licences: Public domain, CC0, CC BY 2.0/3.0/4.0, CC BY-SA 3.0/4.0.
// Attribution is stored per video and shown in the UI, as CC BY / BY-SA require.
//
// renditions[] are the real transcoded derivatives Commons publishes for each
// file (viprop=derivatives), so ARINX offers genuine quality switching rather
// than pretending to have renditions it does not have. Labels are exact pixel
// heights ("360p" = 360px tall).
//
// Files stream from upload.wikimedia.org over HTTP 206 range requests, which is
// what makes scrubbing behave like a streaming player.

export type Rendition = {
  label: string;
  url: string;
  width: number;
  height: number;
  type: string;
};

export type CommonsVideo = {
  title: string;
  category: string;
  sourceUrl: string;
  sourcePage: string;
  thumbnailUrl: string;
  license: string;
  attribution: string;
  durationSec: number;
  renditions: Rendition[];
};

